from flask import Flask, request, redirect, jsonify
import hashlib

app = Flask(__name__)
url_storage = {}
click_stats = {}

@app.route('/shorten', methods=['POST'])
def shorten_url():
    long_url = request.json['long_url']
    short_code = hashlib.md5(long_url.encode()).hexdigest()[:6]
    url_storage[short_code] = long_url
    click_stats[short_code] = 0
    return jsonify(short_code=short_code), 200

@app.route('/<short_code>', methods=['GET'])
def redirect_url(short_code):
    long_url = url_storage.get(short_code)
    if long_url:
        click_stats[short_code] += 1
        return redirect(long_url, code=307)
    return jsonify(error="Not found"), 404

@app.route('/stats/<short_code>', methods=['GET'])
def get_stats(short_code):
    clicks = click_stats.get(short_code, 0)
    return jsonify(clicks=clicks), 200

if __name__ == '__main__':
    app.run(debug=True)
